export const PROTOCOL_VERSION = 1
export const SCHEMA_VERSION = 1
export const PRODUCT_VERSION = "0.1.0-dev.1"

export type Ownership = "experienced" | "told" | "observed"
export type ExperienceKind = "user_message" | "assistant_message" | "tool_success" | "tool_failure" | "tool_unknown" | "preference" | "correction" | "observation"
export type ExperienceInput = {
  sourceKey: string
  scope: string
  kind: ExperienceKind
  ownership: Ownership
  text: string
  observedAt?: number
  evidence?: Record<string, unknown>
  private?: boolean
}
export type Experience = ExperienceInput & { id: number; observedAt: number; recordedAt: number; retracted: boolean }
export type MemoryKind = "preference" | "fact" | "inference" | "episode" | "commitment"
export type Memory = {
  id: string
  revision: number
  scope: string
  kind: MemoryKind
  text: string
  sourceIds: number[]
  status: "active" | "superseded" | "forgotten" | "invalidated"
  pinned: boolean
  private: boolean
  createdAt: number
  updatedAt: number
  supersedes: string | null
}
export type Affect = { emotion: number[]; mood: number[]; updatedAt: number; lastSourceId: number | null; reason: string }
export type TaskStatus = "ready" | "running" | "waiting" | "verifying" | "completed" | "failed" | "cancelled"
export type Task = { id: string; title: string; scope: string; status: TaskStatus; sessionId: string | null; createdAt: number; updatedAt: number; error: string | null }
export type Action = { id: string; taskId: string; tool: string; status: "running" | "succeeded" | "failed" | "unknown"; text: string; revision: string; updatedAt: number }
export type ChatMessage = { id: string; taskId: string; role: "user" | "assistant" | "system"; text: string; createdAt: number }
export type SleepReport = { id: string; status: "completed" | "paused" | "failed"; fromCursor: number; toCursor: number; examined: number; created: number; startedAt: number; finishedAt: number; detail: string }
export type CheckpointInfo = { generation: string; identityId: string; createdAt: number; schemaVersion: number; sha256: string; revision: number; parent: string | null }
import { existsSync, readFileSync, writeFileSync, renameSync } from "node:fs"
import { join, resolve } from "node:path"

/** Stable Windows workspace paths are required by OpenCode's stored session directory. */
export function mountPortable(portableRoot: string): { root: string; release(): void } {
  if (process.platform !== "win32") return { root: portableRoot, release() {} }
  const target = resolve(portableRoot)
  const markerPath = join(target, "drive.json")
  const marker = JSON.parse(readFileSync(markerPath, "utf8")) as { driveId: string; preferredLetter?: string }
  if (typeof marker.driveId !== "string") throw new Error("便携身份标识缺失")
  const normalize = (path: string) => resolve(path).replace(/\\+$/, "").toLowerCase()
  const mappings = () => {
    const result = Bun.spawnSync(["subst.exe"], { stdout: "pipe", stderr: "pipe", windowsHide: true })
    if (result.exitCode !== 0) throw new Error("无法读取 Windows 路径映射")
    const found = new Map<string, string>()
    for (const line of result.stdout.toString().split(/\r?\n/)) {
      const match = /^([A-Z]):\\:\s*=>\s*(.+)$/i.exec(line.trim())
      if (match) found.set(match[1]!.toUpperCase(), match[2]!)
    }
    return found
  }
  const existing = mappings()
  if (marker.preferredLetter && !/^[D-Z]$/.test(marker.preferredLetter)) throw new Error("稳定盘符设置无效")
  const candidates = marker.preferredLetter ? [marker.preferredLetter] : ["X", "Y", "Z", "R", "Q", "P", "N", "M"]
  for (const letter of candidates) {
    const mapped = existing.get(letter)
    const same = mapped !== undefined && normalize(mapped) === normalize(target)
    if (!same && (mapped || existsSync(`${letter}:\\`))) {
      if (marker.preferredLetter) throw new Error(`星杳使用的稳定路径 ${letter}: 已被其他设备占用。请释放该盘符后重试；会话数据未修改。`)
      continue
    }
    const root = `${letter}:\\`
    const created = !same
    if (created) {
      const result = Bun.spawnSync(["subst.exe", `${letter}:`, target], { stdout: "pipe", stderr: "pipe", windowsHide: true })
      if (result.exitCode !== 0) { if (marker.preferredLetter) throw new Error("创建稳定工作路径失败"); continue }
    }
    const mappedIdentity = JSON.parse(readFileSync(join(root, "drive.json"), "utf8")) as { driveId: string }
    if (mappedIdentity.driveId !== marker.driveId || normalize(mappings().get(letter) ?? "") !== normalize(target)) throw new Error("工作路径映射与便携身份不一致")
    if (!marker.preferredLetter) {
      // The identity marker is tiny; keep the previous marker for recovery on exFAT.
      writeFileSync(join(target, "drive.previous.json"), JSON.stringify(marker))
      const next = JSON.stringify({ ...marker, preferredLetter: letter })
      const temporary = join(target, `drive-${crypto.randomUUID()}.json`)
      writeFileSync(temporary, next, { flag: "wx" })
      try { renameSync(temporary, markerPath) } catch { writeFileSync(markerPath, next) }
    }
    let released = false
    return { root, release() {
      if (released || !created) return
      released = true
      if (normalize(mappings().get(letter) ?? "") === normalize(target)) Bun.spawnSync(["subst.exe", `${letter}:`, "/D"], { stdout: "ignore", stderr: "ignore", windowsHide: true })
    } }
  }
  throw new Error("没有可用的稳定盘符，无法保证会话跨设备接续")
}
